          '**[LangSmith](https://www.langchain.com/pricing-langsmith) ist LangChains eigene Observability-Plattform — Tracing ist automatisch für LangChain- und LangGraph-Anwendungen und erfordert die geringste Einrichtung aller Tools hier, wenn Sie bereits auf diesen Frameworks bauen.** Außerhalb des LangChain-Ökosystems funktioniert LangSmith weiterhin über sein SDK, aber der Vorteil des automatischen Tracings verschwindet. Starten Sie kostenlos mit der Developer-Stufe — keine Kreditkarte für die ersten 5.000 Traces/Monat.',
