          'LangSmith va le plus loin dans LangChain et LangGraph spécifiquement — le tracing est automatique si vous construisez déjà avec ces frameworks. Le niveau Plus coûte 39 $/siège/mois plus des unités de calcul (LCU) et de stockage (LSU) facturées à l’usage.',
