          '**[LangSmith](https://www.langchain.com/pricing-langsmith) est la plateforme d’observabilité propre à LangChain — le tracing est automatique pour les applications LangChain et LangGraph et demande le moins de mise en place de tous les outils ici si vous construisez déjà sur ces frameworks.** Hors de l’écosystème LangChain, LangSmith fonctionne toujours via son SDK, mais l’avantage du tracing automatique disparaît. Démarrez gratuitement avec le niveau Developer — aucune carte requise pour les 5 000 premières traces/mois.',
