          '**[Langfuse](https://langfuse.com/pricing) est sous licence MIT et gratuit en auto-hébergement avec toutes les fonctionnalités principales incluses — il n’y a aucune barrière séparant la version auto-hébergée gratuite des niveaux cloud payants.** Langfuse a été racheté par ClickHouse, Inc. en janvier 2026 ; le produit reste open source et auto-hébergeable, et Langfuse Cloud continue de fonctionner sans changement. Démarrez gratuitement en auto-hébergement ou avec le niveau Cloud Hobby — aucune carte requise.',
          'Auto-hébergé (Open Source) : gratuit, illimité, licence MIT, toutes les fonctionnalités principales d’observabilité/évaluation/gestion de prompts. Cloud Hobby : gratuit, 50 000 unités/mois, 2 utilisateurs, rétention des données de 30 jours. Cloud Core : 29 $/mois, 100 000 unités/mois incluses, utilisateurs illimités, rétention de 90 jours, 8 $ par tranche supplémentaire de 100 000 unités. Cloud Pro : 199 $/mois, 100 000 unités/mois incluses, utilisateurs illimités, rétention des données de 3 ans, plus un module Teams à 300 $/mois pour SSO/RBAC. Cloud Enterprise : 2 499 $/mois, ingénieur de support dédié, journaux d’audit, SLA sur mesure. Le Self-Hosted Enterprise (tarifé séparément, associé à un plan commercial ClickHouse) ajoute des API de gestion, un RBAC au niveau projet et le masquage des données côté serveur au socle auto-hébergé gratuit.',
