          'Compromiso: autoalojar significa que asumes el tiempo de actividad, las actualizaciones y el costo de infraestructura — el software "gratis" igual necesita a alguien que lo opere. El límite de 2 usuarios del nivel Cloud Hobby es ajustado para cualquier cosa más allá de un proyecto individual, lo que empuja a los equipos bastante pronto hacia el nivel Core de $29/mes en cuanto más de dos personas necesitan acceso.',
