            q: '¿Qué es la observabilidad de LLM?',
            a: 'La observabilidad de LLM es la práctica de registrar, trazar y monitorear las llamadas API de grandes modelos de lenguaje después de que corren en producción — siguiendo qué se envió, qué regresó, cuánto tardó y cuánto costó. Responde "¿qué pasó en producción?" en lugar de "¿este prompt es bueno?", que es el trabajo de las herramientas de testing previas al despliegue.',
