      faqSection: {
        id: 'faq',
        title: 'Perguntas frequentes',
        faqs: [
          {
            q: 'O que é observabilidade de LLM?',
            a: 'Observabilidade de LLM é a prática de registrar, rastrear e monitorar chamadas de API de grandes modelos de linguagem depois que elas rodam em produção — acompanhando o que foi enviado, o que voltou, quanto tempo levou e quanto custou. Ela responde "o que aconteceu em produção?" em vez de "esse prompt é bom?", que é o trabalho das ferramentas de teste antes do deploy.',
          },
          {
            q: 'A Langfuse é realmente grátis, ou é só um teste?',
            a: 'Fazer self-host da Langfuse é genuinamente grátis para sempre — ela tem licença MIT sem barreira de recursos entre a versão self-hosted gratuita e os níveis pagos na nuvem. A Langfuse Cloud também tem um nível Hobby gratuito (50.000 unidades/mês, 2 usuários) que não é um teste limitado no tempo, embora tenha um teto em vez de ser ilimitado.',
          },
          {
            q: 'Devo escolher LangSmith ou Langfuse se já uso LangChain?',
            a: 'O LangSmith ganha rastreamento automático sem instrumentação manual se você está no LangChain ou LangGraph, o que é uma vantagem real em tempo de configuração. A Langfuse também se integra nativamente com o LangChain e adiciona self-host grátis e uma lista de integrações mais ampla além do LangChain — escolha o LangSmith para a experiência mais alinhada ao LangChain, a Langfuse se quiser flexibilidade para adicionar outros frameworks ou provedores depois sem trocar de ferramenta.',
          },
          {
            q: 'Quanto uma equipe pequena típica paga por observabilidade de LLM por mês?',
            a: 'Uma equipe de 5 pessoas na Langfuse Core paga cerca de $29/mês. A mesma equipe no LangSmith Plus começa em $195/mês só em assentos ($39 × 5) antes das cobranças por uso de LCU/LSU. No Helicone, uma equipe pequena cabe no nível Pro de $79/mês. No PromptLayer, uma equipe de 5 pessoas cabe no nível gratuito até 2.500 requisições/mês, ou $49/mês no Pro além disso.',
          },
          {
            q: 'Como configuro rastreamento básico com a Langfuse?',
            a: 'Crie um projeto gratuito na Langfuse Cloud (ou faça self-host com Docker), instale o SDK da Langfuse ou use uma de suas integrações nativas (OpenAI SDK, LangChain, LlamaIndex, LiteLLM, Vercel AI SDK, e outras), e adicione suas chaves de API pública/secreta da Langfuse como variáveis de ambiente. Os traces das chamadas instrumentadas aparecem imediatamente no dashboard da Langfuse — sem pipeline de ingestão separado para construir.',
          },
          {
            q: 'O PromptLayer é o mesmo que LangSmith ou Langfuse?',
            a: 'Não. O PromptLayer cobre registro de requisições e versionamento de prompts sem um framework de avaliação completo baseado em datasets, e não tem nível self-hosted abaixo de Enterprise. LangSmith e Langfuse adicionam funções de avaliação maduras (pontuação LLM-as-judge, datasets de regressão) além do registro. Use o PromptLayer se registro e versionamento forem genuinamente tudo que você precisa; use LangSmith ou Langfuse se também precisar avaliar sistematicamente a qualidade da saída.',
          },
          {
            q: 'Posso usar mais de uma dessas ferramentas ao mesmo tempo?',
            a: 'Sim, embora raramente valha a pena a sobreposição de custo e manutenção. Uma combinação comum é Langfuse ou LangSmith para rastreamento mais avaliação, junto com o Helicone puramente pelo seu dashboard de custo em nível de proxy em um endpoint específico de alto volume. Rodar as quatro é redundante — escolha uma para suas necessidades principais de rastreamento e avaliação.',
          },
          {
            q: 'Fazer self-host da Langfuse atende automaticamente ao GDPR ou HIPAA?',
            a: 'Não. Fazer self-host mantém os dados em infraestrutura que você controla, o que apoia requisitos de residência de dados, mas a conformidade com GDPR e HIPAA também depende dos seus próprios controles de acesso, criptografia, logs de auditoria e acordos de processamento de dados — o self-host é necessário para algumas posturas de conformidade, mas não é suficiente por si só. O nível cloud Pro da Langfuse lista disponibilidade de HIPAA e relatórios SOC2/ISO27001 para equipes que preferem uma opção gerenciada pronta para conformidade.',
          },
          {
            q: 'Essas quatro ferramentas têm programas de afiliados ou indicação ativos?',
            a: 'Na data da última checagem de fatos deste artigo (27/08/2026), nenhuma das quatro publica um programa público de afiliados baseado em comissão em seu próprio site. A LangChain opera uma Partner Network para integrações de tecnologia e serviços, que é uma estrutura de parceria, não um programa de comissão por indicação. Os links deste artigo são links de produto simples para o site de cada fornecedor, sem relação de afiliado atual.',
          },
          {
            q: 'Esses preços são os mesmos no mundo todo?',
            a: 'Sim — as quatro são assinaturas SaaS globais cobradas em dólar americano. LangSmith, Langfuse, Helicone e PromptLayer não publicam preços específicos por região; uma equipe na UE, no Japão ou no Brasil paga o mesmo preço listado em USD que uma equipe nos EUA, embora a conversão de moeda e as tarifas de cartão do seu próprio banco ou processador de pagamento possam adicionar um pequeno valor variável em cima.',
          },
        ],
      },
