          'تذهب LangSmith إلى أعمق نقطة داخل LangChain وLangGraph تحديدًا — التتبع تلقائي إذا كنت تبني بالفعل بهذين الإطارين. يكلف مستوى Plus 39 دولارًا/مقعد/شهر بالإضافة إلى وحدات حوسبة (LCU) وتخزين (LSU) تُحتسب حسب الاستخدام.',
