          'Helicone هو proxy عكسي: تغيّر رابط الأساس لواجهة API لديك، وتضيف رأسًا واحدًا، ويتم تسجيل كل استدعاء — دون الحاجة إلى غلاف SDK. الأسرع بين الأربعة لإضافته إلى قاعدة كود موجودة.',
