          '**[Langfuse](https://langfuse.com/pricing) مرخّصة بموجب MIT ومجانية للاستضافة الذاتية مع تضمين جميع الميزات الأساسية — لا يوجد حاجز ميزات يفصل بين النسخة المستضافة ذاتيًا المجانية والمستويات السحابية المدفوعة.** استحوذت ClickHouse, Inc. على Langfuse في يناير 2026؛ يبقى المنتج مفتوح المصدر وقابلاً للاستضافة الذاتية، وتستمر Langfuse Cloud في العمل دون تغيير. ابدأ مجانًا بالاستضافة الذاتية أو مستوى Cloud Hobby — دون الحاجة إلى بطاقة.',
